(function(){
"use strict";
const landing=document.getElementById("landing-page"),auth=document.getElementById("auth-page"),workspace=document.getElementById("workspace"),shared=document.getElementById("shared-view"),modal=document.getElementById("modal-root"),toastBox=document.getElementById("toast-region");
const S={page:"landing",mode:"login",view:"overview",data:null,trust:null,joinPreview:null,businessPeriod:"monthly",businessHistoryExpanded:false,businessFilter:"all",businessSearch:"",busy:false,supabaseAuth:false,authClient:null,authNotice:""};
const icon={overview:"▦",groups:"♧",passport:"▤",trust:"✓",marketplace:"⌂",activity:"⌁",settings:"⚙"};
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function cash(v){return new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(Number(v||0));}
function date(v){const d=new Date(v);return !v||isNaN(d)?"Date to be agreed":new Intl.DateTimeFormat("en-NG",{day:"numeric",month:"short"}).format(d);}
function dueNow(v){return String(v||"").slice(0,10)<=new Date().toISOString().slice(0,10);}
function initials(v){return String(v||"TA").trim().split(/\s+/).slice(0,2).map(x=>x[0]||"").join("").toUpperCase();}
function theme(v){document.documentElement.dataset.theme=v||"system";}
function page(v){S.page=v;landing.classList.toggle("hidden",v!=="landing");auth.classList.toggle("hidden",v!=="auth");workspace.classList.toggle("hidden",v!=="app");shared.classList.toggle("hidden",v!=="share");window.scrollTo(0,0);}
async function api(url,method,body){const o={method:method||"GET",credentials:"same-origin",headers:{}};if(body!==undefined){o.headers["Content-Type"]="application/json";o.body=JSON.stringify(body);}if(S.authClient){const {data}=await S.authClient.auth.getSession();if(data.session?.access_token)o.headers.Authorization="Bearer "+data.session.access_token;}if(!Object.keys(o.headers).length)delete o.headers;const r=await fetch(url,o);let j={};try{j=await r.json();}catch(e){}if(!r.ok)throw new Error(j.error||"Something went wrong.");return j;}
function toast(s,error){toastBox.innerHTML="<div class='toast "+(error?"toast-error":"")+"'><i></i><span>"+esc(s)+"</span><button data-action='toast-close'>×</button></div>";clearTimeout(toast.t);toast.t=setTimeout(()=>toastBox.innerHTML="",4200);}
function showAuth(mode){S.mode=mode;S.authNotice="";page("auth");renderAuth();}
function renderAuth(){
 const signup=S.mode==="signup";
 auth.innerHTML="<div class='auth-shell'><aside class='auth-aside'><button class='brand auth-brand' data-action='home'><span class='brand-mark'><b>TA</b><i></i></span><span class='brand-word'><strong>Trust Ajo</strong><small>Save together. Build trust.</small></span></button><div class='auth-quote'><span class='quote-mark'>“</span><h1>Good circles are built on clear promises.</h1><p>Keep every contribution visible, every payout turn understood, and every financial step in your hands.</p><div class='auth-mini-stat'><b>TA</b><span><strong>Save together, with clarity.</strong><small>Trust Ajo · community savings</small></span></div></div><small class='auth-aside-foot'>Built around people. Designed for trust.</small></aside><section class='auth-panel'><div class='auth-top'><button class='text-link' data-action='home'>← Back to home</button><span>"+(signup?"Already have an account?":"New to Trust Ajo?")+" <button class='inline-link' data-action='"+(signup?"login":"signup")+"'>"+(signup?"Sign in":"Create an account")+"</button></span></div><div class='auth-form-wrap'><small class='section-kicker'>WELCOME TO TRUST AJO</small><h2>"+(signup?"Create your space.":"Good to see you again.")+"</h2><p class='auth-subtitle'>"+(signup?"Set up your profile and bring your savings plans together.":"Sign in to see your circles and financial progress.")+"</p>"+
 (signup?"<form data-form='register' class='auth-form'><label>Full name<input name='name' required minlength='2' placeholder='e.g. Adaeze Okafor'></label><label>Email address<input name='email' type='email' required placeholder='you@example.com'></label><label>Business or project name <small>OPTIONAL</small><input name='businessName' placeholder='What are you building?'></label><label>Business type <small>OPTIONAL</small><input name='businessType' placeholder='Fashion, food, creative'></label><label>Password<input type='password' name='password' required minlength='8' placeholder='At least 8 characters'></label><button class='btn btn-primary btn-full btn-lg' type='submit'>Create account ↗</button><p class='form-note'>No real identity numbers, bank details, or funds are needed.</p></form>":"<form data-form='login' class='auth-form'><label>Email address<input name='email' type='email' required placeholder='you@example.com'></label><label>Password<input type='password' name='password' required placeholder='Your password'></label><button class='btn btn-primary btn-full btn-lg' type='submit'>Sign in ↗</button></form><div class='auth-divider'>OR OPEN SAMPLE WORKSPACE</div><button class='btn btn-sample btn-full' data-action='sample-workspace'>✦ &nbsp; Enter sample workspace</button><p class='form-note'>Synthetic activity only. No real payment or identity checks happen.</p>")+
 "<p class='auth-bottom'>Privacy first · Consent-led sharing <button data-action='help'>About Trust Ajo</button></p></div></section></div>";
 if(S.supabaseAuth){auth.querySelector(".auth-divider")?.remove();const sample=auth.querySelector("[data-action='sample-workspace']");if(sample){sample.nextElementSibling?.remove();sample.remove();}}
 if(S.authNotice)auth.querySelector(".auth-subtitle")?.insertAdjacentHTML("afterend","<p class='form-note' role='status'>"+esc(S.authNotice)+"</p>");
}
function nav(id,label){return"<button class='side-link "+(S.view===id?"active":"")+"' data-view='"+id+"'><span>"+icon[id]+"</span>"+label+"</button>";}
function heading(){return({overview:"Your overview",groups:"Ajo circles",passport:"Business progress",trust:"Trust Engine",marketplace:"Marketplace",activity:"Activity & records",settings:"Settings"})[S.view]||"Your overview";}
function groupCard(g){
 const pct=g.memberCount?Math.round(g.paidThisCycle/g.memberCount*100):0;
 const faces=(g.members||[]).slice(0,4).map((m,i)=>"<span class='face face-"+i+"'>"+esc(initials(m.name))+"</span>").join("");
 const action=g.memberCount<g.capacity?"<span class='pill-wait'>Waiting for "+(g.capacity-g.memberCount)+" more member(s)</span>":(!dueNow(g.nextDueAt)?"<span class='pill-wait'>Contributions open "+date(g.nextDueAt)+"</span>":(S.data.paymentMode==="flutterwave-test"?"<button class='btn btn-primary btn-small' data-action='pay-now' data-id='"+esc(g.id)+"'>Pay with Flutterwave · test</button>":"<button class='btn btn-primary btn-small' data-action='details' data-id='"+esc(g.id)+"'>Record contribution</button>"));
 return"<article class='group-card'><div class='group-top'><span class='group-symbol'>♧</span><span class='cycle-tag'>"+esc(g.frequency)+"</span><button class='more' data-action='details' data-id='"+esc(g.id)+"' aria-label='View "+esc(g.name)+" details'>···</button></div><h3>"+esc(g.name)+"</h3><p>"+esc(g.purpose||"A shared savings circle")+"</p><div class='group-money'><div><small>CONTRIBUTION</small><strong>"+cash(g.contributionAmount)+"</strong><i>per "+esc(g.frequency.toLowerCase())+" cycle</i></div><div class='member-count'><strong>"+g.memberCount+"<small>/"+g.capacity+"</small></strong><i>members</i></div></div><div class='progress-caption'><span>Cycle progress</span><b>"+g.paidThisCycle+" of "+g.memberCount+" recorded</b></div><div class='progress'><span style='width:"+pct+"%'></span></div><div class='group-foot'><div class='faces'>"+faces+"</div><span>Due "+date(g.nextDueAt)+"</span></div><div class='group-actions'>"+(g.myContributionStatus==="due"?action:"<span class='pill-good'>✓ Recorded this cycle</span>")+"<button class='text-link' data-action='details' data-id='"+esc(g.id)+"'>View circle →</button></div></article>";
}
function card(label,value,note,sym){return"<article class='metric-card'><div><small>"+label+"</small><span class='metric-symbol'>"+sym+"</span></div><strong>"+value+"</strong><p>"+note+"</p></article>";}
function overview(){
 const d=S.data,p=d.passport,groups=d.groups||[],first=(d.user.name||"there").split(" ")[0],next=groups.slice().sort((a,b)=>new Date(a.nextDueAt)-new Date(b.nextDueAt))[0];
 const groupContent=groups.length?groups.slice(0,2).map(groupCard).join(""):"<div class='empty'><b>Your first circle starts here.</b><p>Create one and set the rhythm with your people.</p><button class='btn btn-primary btn-small' data-action='new-group'>Create a circle</button></div>";
 return "<div class='welcome-row'><div><small class='section-kicker'>YOUR CIRCLES, AT A GLANCE</small><h1>Welcome back, "+esc(first)+".</h1><p>Keep your circle plans and contribution records in one clear place.</p></div><button class='btn btn-primary' data-action='new-group'>Create an Ajo circle ↗</button></div><section class='overview-hero'><div><span class='hero-kicker'>✳ &nbsp; COMMUNITY SAVINGS, MADE CLEAR</span><h2>When the circle is clear,<br><em>everyone can move forward.</em></h2><p>Agree on the schedule, follow each contribution, and keep the payout order visible to members.</p><button class='btn btn-light' data-view='groups'>Explore your circles →</button></div><div class='circle-emblem'><span class='emblem-ring'></span><b>TA</b><i>AO</i><i>DE</i><i>AB</i><i>TL</i></div></section><div class='metrics-grid'>"+card("AJO CONTRIBUTION ENTRIES",String(p.contributionCount),"Saved in your activity record","↗")+card("ACTIVE AJO CIRCLES",String(groups.length),"Circles you belong to","♧")+card("NEXT CONTRIBUTION",next?date(next.nextDueAt):"—",next?cash(next.contributionAmount)+" · "+esc(next.name):"No upcoming circle","◷")+"</div><div class='overview-grid'><section class='panel main-panel'><div class='panel-head'><div><small class='section-kicker'>YOUR CIRCLES</small><h2>Ajo, together.</h2></div><button class='text-link' data-view='groups'>All circles →</button></div><div class='group-stack'>"+groupContent+"</div></section><aside class='overview-side'><section class='panel passport-mini'><div class='panel-head'><div><small class='section-kicker'>BUSINESS TRACKER</small><h2>Business progress</h2></div><span class='passport-icon'>↗</span></div><div class='passport-overview-copy'><strong>Know what came in and went out.</strong><p>Keep a simple record of your business activity, week by week.</p></div><div class='mini-metrics'><div><small>Income this month</small><b>"+cash(businessBuckets("monthly").totals.income)+"</b></div><div><small>Expenses this month</small><b>"+cash(businessBuckets("monthly").totals.expense)+"</b></div><div><small>Records</small><b>"+(S.data.businessEntries||[]).length+"</b></div></div><button class='btn btn-outline btn-full' data-view='passport'>Open business progress ↗</button></section><section class='safety-card'><span>✓</span><div><small class='section-kicker'>TRUST ENGINE NOTE</small><strong>A screenshot can’t confirm a payment.</strong><p>Check the provider record before releasing goods.</p><button class='text-link' data-view='trust'>Check a payment →</button></div></section>"+(next?"<section class='upcoming panel'><span>◷</span><div><small class='section-kicker'>NEXT CONTRIBUTION</small><b>"+esc(next.name)+"</b><small>"+cash(next.contributionAmount)+" · due "+date(next.nextDueAt)+"</small></div><button data-view='groups' aria-label='View circles'>→</button></section>":"")+"</aside></div>";
}
function groupsPage(){
 const gs=S.data.groups||[],preview=S.joinPreview;
 const previewCard=preview?"<section class='join-preview panel' aria-live='polite'><small class='section-kicker'>REVIEW BEFORE JOINING</small><h2>"+esc(preview.group.name)+"</h2><p>"+esc(preview.group.purpose||"A shared savings circle")+"</p><div class='join-terms'><div><small>CONTRIBUTION</small><b>"+cash(preview.group.contributionAmount)+" / "+esc(preview.group.frequency.toLowerCase())+"</b></div><div><small>NEXT DUE</small><b>"+date(preview.group.nextDueAt)+"</b></div><div><small>MEMBERS</small><b>"+preview.group.memberCount+" / "+preview.group.capacity+"</b></div></div><div class='join-rotation'><small>AGREED PAYOUT ORDER</small><b>"+esc((preview.group.payoutOrder||[]).join(" → "))+"</b></div><p class='cycle-start-note'>Contributions begin when the circle reaches its agreed capacity.</p>"+(preview.conflict?"<p class='join-conflict' role='alert'>Schedule conflict: this circle overlaps "+esc(preview.conflict.groupName)+" on "+date(preview.conflict.date)+". Ask the organizer to agree a different date first.</p>":"<p class='join-clear'>No same-day due-date clash found in the next 12 months. Review the amount and schedule before joining.</p>")+"<div class='modal-actions'><button class='btn btn-quiet' data-action='dismiss-join-preview'>Cancel</button><button class='btn btn-primary' data-action='confirm-join' "+(preview.conflict?"disabled":"")+">I agree, join this circle</button></div></section>":"";
 const modeNote=S.data.paymentMode==="flutterwave-test"?"Flutterwave test checkout is available when a circle is full. Test transactions do not move real money.":"Sample contributions only add a local ledger entry; no money moves.";
 return "<div class='page-head'><div><small class='section-kicker'>SAVE AS A CIRCLE</small><h1>Ajo circles</h1><p>Agree the amount, schedule, and turn order before the first contribution.</p></div><button class='btn btn-primary' data-action='new-group'>+ Create a circle</button></div><div class='notice'>i <span>"+modeNote+"</span><button data-action='help'>How it works</button></div><section class='panel join-panel'><div><small class='section-kicker'>JOIN A CIRCLE</small><h2>Have an invite code?</h2><p>Enter a code to review the commitment first. We’ll check capacity and compare due dates before you confirm.</p></div><form data-form='join-group' class='join-form'><label for='join-code'>Invite code</label><div><input id='join-code' name='joinCode' required minlength='8' maxlength='16' autocomplete='off' autocapitalize='characters' placeholder='8–16 character code'><button class='btn btn-outline' type='submit'>Review circle</button></div></form></section>"+previewCard+"<div class='group-grid'>"+(gs.length?gs.map(groupCard).join(""):"<div class='empty'><b>No circles yet</b><p>Create your first savings circle.</p><button class='btn btn-primary' data-action='new-group'>Create a circle</button></div>")+"</div><section class='panel rotation'><div class='panel-head'><div><small class='section-kicker'>ROTATION, MADE CLEAR</small><h2>What every member can see</h2></div><span class='rotation-mark'>TA</span></div><div class='rotation-grid'><div><b>01</b><strong>Contribution rhythm</strong><span>Amount, frequency, next due date.</span></div><div><b>02</b><strong>Cycle progress</strong><span>How many contributions are recorded.</span></div><div><b>03</b><strong>Payout order</strong><span>The rotation the group agreed to follow.</span></div></div></section>";
}

function businessBuckets(period){
 const today=new Date();today.setUTCHours(0,0,0,0);const buckets=[];
 if(period==="daily"){
  for(let offset=13;offset>=0;offset--){const start=new Date(today);start.setUTCDate(start.getUTCDate()-offset);const end=new Date(start);end.setUTCDate(end.getUTCDate()+1);buckets.push({start,end,label:new Intl.DateTimeFormat("en-NG",{day:"numeric",month:"short",timeZone:"UTC"}).format(start)});}
 }else if(period==="weekly"){
  const monday=new Date(today);monday.setUTCDate(monday.getUTCDate()-((monday.getUTCDay()+6)%7));
  for(let offset=7;offset>=0;offset--){const start=new Date(monday);start.setUTCDate(start.getUTCDate()-offset*7);const end=new Date(start);end.setUTCDate(end.getUTCDate()+7);buckets.push({start,end,label:"Week of "+new Intl.DateTimeFormat("en-NG",{day:"numeric",month:"short",timeZone:"UTC"}).format(start)});}
 }else if(period==="yearly"){
  for(let offset=4;offset>=0;offset--){const year=today.getUTCFullYear()-offset;const start=new Date(Date.UTC(year,0,1)),end=new Date(Date.UTC(year+1,0,1));buckets.push({start,end,label:String(year)});}
 }else{
  for(let offset=11;offset>=0;offset--){const start=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth()-offset,1)),end=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,1));buckets.push({start,end,label:new Intl.DateTimeFormat("en-NG",{month:"short",timeZone:"UTC"}).format(start)});}
 }
 for(const bucket of buckets){bucket.income=0;bucket.expense=0;bucket.count=0;}
 for(const entry of S.data.businessEntries||[]){const when=new Date(String(entry.entryDate||"")+"T00:00:00Z");if(Number.isNaN(when.getTime()))continue;const bucket=buckets.find(item=>when>=item.start&&when<item.end);if(!bucket)continue;bucket[entry.type==="income"?"income":"expense"]+=Number(entry.amount)||0;bucket.count++;}
 const totals=buckets.reduce((sum,item)=>({income:sum.income+item.income,expense:sum.expense+item.expense,count:sum.count+item.count}),{income:0,expense:0,count:0});totals.net=totals.income-totals.expense;
 return {buckets,totals};
}
function businessPeriodLabel(period){return({daily:"Last 14 days",weekly:"Last 8 weeks",monthly:"Last 12 months",yearly:"Last 5 years"})[period]||"Last 12 months";}
function filteredBusinessEntries(){
 const search=String(S.businessSearch||"").trim().toLowerCase(),filter=S.businessFilter||"all";
 return(S.data.businessEntries||[]).filter(entry=>{
  if(filter!=="all"&&entry.type!==filter)return false;
  if(!search)return true;
  return[entry.category,entry.note,entry.type,entry.entryDate,entry.amount].some(value=>String(value||"").toLowerCase().includes(search));
 });
}
function businessPage(){
 const period=S.businessPeriod||"monthly",entries=S.data.businessEntries||[],filtered=filteredBusinessEntries(),summary=businessBuckets(period),max=Math.max(1,...summary.buckets.flatMap(x=>[x.income,x.expense]));
 const chart=summary.buckets.map(bucket=>"<div class='business-chart-column' aria-label='"+esc(bucket.label+": income "+cash(bucket.income)+", expenses "+cash(bucket.expense))+"'><div class='business-bars' aria-hidden='true'><span class='business-bar income-bar' style='height:"+(bucket.income?Math.max(3,Math.round(bucket.income/max*112)):0)+"px'></span><span class='business-bar expense-bar' style='height:"+(bucket.expense?Math.max(3,Math.round(bucket.expense/max*112)):0)+"px'></span></div><small>"+esc(bucket.label)+"</small></div>").join("");
 const shown=S.businessHistoryExpanded?filtered:filtered.slice(0,8),sampleProfile=Boolean(S.data.passport&&S.data.passport.sampleProfile),goal=Number(S.data.user.monthlyIncomeGoal||0),monthIncome=businessBuckets("monthly").totals.income,goalPct=goal?Math.min(100,Math.round(monthIncome/goal*100)):0;
 const rows=shown.map(entry=>"<article class='business-entry'><span class='business-entry-mark "+(entry.type==="income"?"income-mark":"expense-mark")+"'>"+(entry.type==="income"?"↗":"↙")+"</span><div class='business-entry-main'><strong>"+esc(entry.category)+(String(entry.id).startsWith("seed-business-")?" <span class='sample-record-tag'>Sample</span>":"")+"</strong><small>"+date(entry.entryDate)+(entry.note?" · "+esc(entry.note):"")+"</small></div><span class='business-entry-type'>"+(entry.type==="income"?"Income":"Expense")+"</span><strong class='business-entry-amount "+(entry.type==="income"?"income-text":"expense-text")+"'>"+(entry.type==="income"?"+":"−")+cash(entry.amount)+"</strong><div class='business-row-actions'><button class='business-edit' data-action='edit-business-entry' data-id='"+esc(entry.id)+"'>Edit</button><button class='business-delete' data-action='delete-business-entry' data-id='"+esc(entry.id)+"' aria-label='Delete "+esc(entry.category)+" record'>Delete</button></div></article>").join("");
 const goalPanel=goal?"<section class='panel business-goal-card'><div><small class='section-kicker'>THIS MONTH’S INCOME GOAL</small><h2>"+cash(monthIncome)+" <span>of "+cash(goal)+" recorded</span></h2><p>"+(goalPct>=100?"Your recorded income has reached this month’s goal.":cash(Math.max(0,goal-monthIncome))+" to go based on your entries.")+"</p><div class='goal-progress' role='progressbar' aria-label='Monthly income goal progress' aria-valuemin='0' aria-valuemax='100' aria-valuenow='"+goalPct+"'><span style='width:"+goalPct+"%'></span></div></div><button class='btn btn-outline' data-action='set-business-goal'>Edit goal</button></section>":"<section class='panel business-goal-card goal-empty'><div><small class='section-kicker'>MONTHLY INCOME GOAL</small><h2>Set a target for this month</h2><p>Track your recorded income against a goal you choose.</p></div><button class='btn btn-outline' data-action='set-business-goal'>Set a goal</button></section>";
 const rowsContent=rows?"<div class='business-entry-list'>"+rows+"</div>":(entries.length&&filtered.length===0?"<div class='empty business-empty'><b>No matching records.</b><p>Try a different search or clear the filters.</p><button class='btn btn-outline' data-action='clear-business-search'>Clear search and filters</button></div>":"<div class='empty business-empty'><b>Your business record starts here.</b><p>Add money in or money out to see your progress over time.</p><button class='btn btn-primary' data-action='add-business-entry'>Add your first record</button></div>");
 return "<div class='page-head business-page-head'><div><small class='section-kicker'>YOUR BUSINESS, AT A GLANCE</small><h1>Business progress</h1><p>Record money coming in and going out. See how your business changes over time.</p></div><button class='btn btn-primary' data-action='add-business-entry'>+ Add a record</button></div><div class='business-notice'>"+(sampleProfile?"<strong>SAMPLE RECORDS</strong> This account includes fictional example figures. Edit or delete them before using this as your business record.":"<strong>YOUR RECORDS</strong> Only the entries you add appear here.")+"</div><div class='business-metrics'>"+card("MONEY IN",cash(summary.totals.income),businessPeriodLabel(period),"↗")+card("MONEY OUT",cash(summary.totals.expense),businessPeriodLabel(period),"↙")+card("NET RECORDED",(summary.totals.net<0?"−":"")+cash(Math.abs(summary.totals.net)),"Money in minus money out · "+summary.totals.count+" entries","=")+"</div>"+goalPanel+"<section class='panel business-chart-panel'><div class='panel-head business-chart-head'><div><small class='section-kicker'>INCOME AND EXPENSES</small><h2>Track your progress</h2><p>Compare what came in with what went out.</p></div><div class='period-tabs' role='group' aria-label='Chart time range'>"+["daily","weekly","monthly","yearly"].map(p=>"<button class='period-tab "+(period===p?"active":"")+"' data-action='business-period' data-period='"+p+"' aria-pressed='"+(period===p)+"'>"+({daily:"Daily",weekly:"Weekly",monthly:"Monthly",yearly:"Yearly"})[p]+"</button>").join("")+"</div></div><div class='business-legend'><span><i class='legend-income'></i>Money in</span><span><i class='legend-expense'></i>Money out</span></div><div class='business-chart' role='list' aria-label='Business income and expense chart'>"+chart+"</div><p class='chart-footnote'>"+businessPeriodLabel(period)+" · Based on your saved records.</p></section><section class='panel business-ledger'><div class='panel-head business-ledger-head'><div><small class='section-kicker'>YOUR BUSINESS LEDGER</small><h2>Recent records</h2><p>Showing "+filtered.length+" of "+entries.length+" record"+(entries.length===1?"":"s")+"</p></div><div class='business-ledger-actions'><button class='btn btn-outline' data-action='export-business-csv' "+(filtered.length?"":"disabled")+">Export CSV</button><button class='btn btn-primary' data-action='add-business-entry'>+ Add record</button></div></div><div class='business-ledger-tools'><label class='business-search-label' for='business-search'>Search records</label><input id='business-search' type='search' value='"+esc(S.businessSearch||"")+"' placeholder='Category, note, type, date or amount'><div class='business-filters' role='group' aria-label='Filter business records'>"+[ ["all","All"],["income","Money in"],["expense","Money out"] ].map(item=>"<button class='business-filter "+((S.businessFilter||"all")===item[0]?"active":"")+"' data-action='business-filter' data-filter='"+item[0]+"' aria-pressed='"+((S.businessFilter||"all")===item[0])+"'>"+item[1]+"</button>").join("")+"</div></div>"+rowsContent+(filtered.length>8?"<button class='text-link business-history-toggle' data-action='toggle-business-history'>"+(S.businessHistoryExpanded?"Show recent only":"Show all "+filtered.length+" records →")+"</button>":"")+"</section><p class='business-disclaimer'>These are manually entered records. They are not bank-verified, audited accounts, tax records, or proof of payment. Ajo contributions stay in your Ajo circle history.</p>";
}
function passportPage(){return businessPage();}
function trustPage(){
 const r=S.trust;return"<div class='page-head'><div><small class='section-kicker'>PAYMENT REFERENCE REVIEW</small><h1>Trust Engine</h1><p>Check a payment reference against fictional sample records.</p></div><span class='trust-badge'>✓ Review with care</span></div><div class='warning'><b>!</b><div><strong>A screenshot is not a payment confirmation.</strong><span>This local sample checker matches sample references only. A real check needs an authorised provider connection.</span></div></div><div class='trust-layout'><section class='panel check-panel'><div class='panel-head'><div><small class='section-kicker'>CHECK A REFERENCE</small><h2>Look for the matching credit.</h2></div><span class='passport-icon'>✓</span></div><p>Enter a reference and amount. The sample checker compares them with fictional sample records.</p><form data-form='trust' class='trust-form'><label>Amount received<input type='number' min='1' name='amount' required placeholder='e.g. 30000'></label><label>Payment reference<input name='reference' required placeholder='e.g. TA-SAMPLE-730145'></label><button class='btn btn-primary' type='submit'>Check sample source ↗</button></form>"+(r?"<div class='check-result "+(r.verified?"good":"review")+"'><b>"+(r.verified?"✓":"!")+"</b><div><strong>"+(r.verified?"Sample credit matched":"No sample credit found")+"</strong><p>"+esc(r.message)+"</p></div></div>":"")+"<div class='sample-refs'><b>Try a sample</b><button data-action='sample-ref' data-ref='TA-SAMPLE-730145' data-amount='30000'>TA-SAMPLE-730145 <strong>₦30,000</strong></button><button data-action='sample-ref' data-ref='TA-SAMPLE-110948' data-amount='18500'>TA-SAMPLE-110948 <strong>₦18,500</strong></button></div></section><aside class='trust-side'><article><small>01</small><h3>Wait for the source record.</h3><p>Check before releasing goods or closing a contribution.</p></article><article><small>02</small><h3>Review unusual activity.</h3><p>An unexpected amount is a signal to review, not proof of wrongdoing.</p></article><div class='safe-note'>▣ &nbsp; The sample check runs locally and logs an event.</div></aside></div>";
}
function marketPage(){return"<div class='page-head'><div><small class='section-kicker'>MADE BY THE CIRCLE</small><h1>Member marketplace</h1><p>Discover products from makers and sellers in the community.</p></div><span class='market-stamp'>LOCAL MAKERS ✳</span></div><div class='notice'>✳ <span><b>Orders are sample records.</b> Saving an order won’t charge you or contact a seller.</span></div><div class='market-grid'>"+(S.data.products||[]).map(p=>"<article class='product-card'><div class='product-art art-"+esc(p.color)+"'><small>"+esc(p.category)+"</small><div class='product-object obj-"+esc(p.color)+"'></div><b>TA</b></div><div class='product-info'><small>"+esc(p.seller)+"</small><h3>"+esc(p.name)+"</h3><p>"+esc(p.description)+"</p><div><strong>"+cash(p.price)+"</strong><button class='btn btn-small btn-dark' data-action='buy' data-id='"+esc(p.id)+"'>Save sample order</button></div></div></article>").join("")+"</div><section class='panel market-foot'><b>✦</b><div><strong>Keep growth close to home.</strong><p>Connect members to local makers and keep sample activity together.</p></div><button class='text-link' data-action='help'>About Trust Ajo →</button></section>";}
function activityPage(){
 const rows=S.data.activity||[],audit=S.data.audit||[];
 return"<div class='page-head'><div><small class='section-kicker'>ONE SHARED RECORD</small><h1>Activity & records</h1><p>Review Ajo contribution records, sample orders, and account actions.</p></div><button class='btn btn-outline' data-action='refresh'>↻ Refresh activity</button></div><div class='notice'>i <span>Local sample records are not bank statements or proof of real payments.</span></div><section class='panel table-panel'><div class='panel-head'><div><small class='section-kicker'>RECENT ACTIVITY</small><h2>Your record</h2></div><small>"+rows.length+" items</small></div>"+(rows.length?"<div class='table-scroll'><table><thead><tr><th>ACTIVITY</th><th>CATEGORY</th><th>REFERENCE</th><th>WHEN</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody>"+rows.map(a=>"<tr><td><b>"+esc(a.title)+"</b></td><td>"+esc(a.category)+"</td><td class='mono'>"+esc(a.reference||"—")+"</td><td>"+date(a.createdAt)+"</td><td>"+(a.direction==="out"?"−":"+")+cash(a.amount)+"</td><td><span class='table-status'>"+esc(String(a.status||"logged").replaceAll("_"," "))+"</span></td></tr>").join("")+"</tbody></table></div>":"<div class='empty'><b>No activity yet.</b></div>")+"</section><section class='panel audit-panel'><div class='panel-head'><div><small class='section-kicker'>PRIVACY TRAIL</small><h2>Account actions</h2></div><span>▣</span></div>"+(audit.length?audit.map(a=>"<div class='audit-row'><i></i><div><b>"+esc(a.action.replaceAll("."," · "))+"</b><small>"+esc(a.detail)+"</small></div><time>"+date(a.createdAt)+"</time></div>").join(""):"<div class='empty'><b>Your activity trail starts here.</b><p>Settings, verification and sharing actions appear here.</p></div>")+"</section>";
}
function toggle(name,title,detail,on){return"<label class='toggle-row'><span><b>"+title+"</b><small>"+detail+"</small></span><input type='checkbox' name='"+name+"' "+(on?"checked":"")+"><i></i></label>";}
function settingsPage(){
 const u=S.data.user,p=u.preferences||{};
 const storageNote=S.data.storageMode==="supabase"?"Storage: your configured Supabase project. This app uses one shared JSON state record; use sample data only.":"Storage: local server memory. Data is cleared when the server restarts.";
 const paymentNote=S.data.paymentMode==="flutterwave-test"?"Payments: Flutterwave test mode only. Test transactions do not move real money.":"Payments: local ledger only. No checkout or money transfer is enabled.";
 return "<div class='page-head'><div><small class='section-kicker'>MAKE IT YOURS</small><h1>Settings</h1><p>Update your profile and control the preferences saved to this account.</p></div><span class='settings-mark'>⚙</span></div><form data-form='settings' class='settings-form'><section class='panel settings-card'><div class='panel-head'><div><small class='section-kicker'>APP APPEARANCE</small><h2>Choose your theme</h2></div><span>✦</span></div><p>Use light, dark, or follow your device setting.</p><select name='theme' id='theme-select'><option value='system' "+(p.theme==="system"?"selected":"")+">System</option><option value='light' "+(p.theme==="light"?"selected":"")+">Light</option><option value='dark' "+(p.theme==="dark"?"selected":"")+">Dark</option></select><div class='theme-tiles'><button type='button' data-theme-choice='light' class='"+(p.theme==="light"?"selected":"")+"'><i class='light-swatch'></i><b>Light</b><small>Warm, open and calm</small></button><button type='button' data-theme-choice='dark' class='"+(p.theme==="dark"?"selected":"")+"'><i class='dark-swatch'></i><b>Dark</b><small>Soft contrast, low light</small></button><button type='button' data-theme-choice='system' class='"+(p.theme==="system"?"selected":"")+"'><i class='system-swatch'></i><b>System</b><small>Follow your device</small></button></div></section><section class='panel settings-card'><div class='panel-head'><div><small class='section-kicker'>PROFILE DETAILS</small><h2>Your business profile</h2></div><span>▤</span></div><p>These details help identify your business in your workspace.</p><div class='settings-inputs'><label>Business or project name<input name='businessName' maxlength='80' value='"+esc(u.businessName||"")+"' placeholder='What are you building?'></label><label>Business type<input name='businessType' maxlength='80' value='"+esc(u.businessType||"")+"' placeholder='Fashion, food, creative'></label></div><div class='readonly-email'>▣ <div><b>Sign-in email</b><small>"+esc(u.email)+"</small></div><i>Account detail</i></div></section><section class='panel settings-card'><div class='panel-head'><div><small class='section-kicker'>REMINDERS & UPDATES</small><h2>Saved preferences</h2></div><span>⌁</span></div><p>These preferences are saved, but this version does not send reminders, summaries, or alerts.</p>"+toggle("contributionReminders","Contribution reminders","Preference for a future reminder service.",p.contributionReminders)+toggle("weeklyDigest","Weekly activity summary","Preference for a future summary service.",p.weeklyDigest)+toggle("shareAlerts","Passport access alerts","Preference for a future alert service.",p.shareAlerts)+"</section><section class='privacy-box'><b>▣</b><div><strong>App status and privacy</strong><p>"+esc(storageNote)+" "+esc(paymentNote)+" Identity checks are mock-only. Do not enter real identity, bank, or card details.</p><button type='button' class='text-link' data-action='help'>Read how the app works →</button></div></section><div class='settings-actions'><button class='btn btn-primary btn-lg' type='submit'>Save settings ↗</button><button class='btn btn-quiet' type='button' data-action='logout'>Sign out</button></div></form>";
}
function content(){switch(S.view){case"groups":return groupsPage();case"passport":return passportPage();case"trust":return trustPage();case"marketplace":return marketPage();case"activity":return activityPage();case"settings":return settingsPage();default:return overview();}}
function renderApp(){
 if(!S.data)return;theme(S.data.user.preferences.theme);
 workspace.innerHTML="<div class='app-shell'><aside class='sidebar'><button class='brand app-brand' data-action='overview'><span class='brand-mark'><b>TA</b><i></i></span><span class='brand-word'><strong>Trust Ajo</strong><small>Save together. Build trust.</small></span></button><div class='workspace-switch'><span>"+esc(initials(S.data.user.businessName||S.data.user.name))+"</span><div><strong>"+esc(S.data.user.businessName||"My workspace")+"</strong><small>Personal space</small></div><b>⌄</b></div><small class='side-caption'>YOUR SPACE</small><nav>"+nav("overview","Overview")+nav("groups","Ajo circles")+nav("passport","Business progress")+nav("trust","Trust Engine")+nav("marketplace","Marketplace")+"</nav><small class='side-caption side-caption-gap'>RECORDS</small><nav>"+nav("activity","Activity & records")+nav("settings","Settings")+"</nav><div class='side-bottom'><div class='side-help'><span>?</span><strong>New to Trust Ajo?</strong><p>See how your circles and business records fit together.</p><button class='text-link' data-action='help'>Explore the guide →</button></div><div class='side-account'><span class='avatar'>"+esc(initials(S.data.user.name))+"</span><div><strong>"+esc(S.data.user.name)+"</strong><small>"+esc(S.data.user.email)+"</small></div><button data-view='settings'>···</button></div></div></aside><section class='main-pane'><header class='topbar'><div class='top-left'><button class='mobile-menu' data-action='sidebar-toggle'>☰</button><span>Trust Ajo <i>/</i> <strong>"+heading()+"</strong></span><small class='mode-badge'><i></i> "+(S.data.paymentMode==="flutterwave-test"?"FLUTTERWAVE TEST":"RECORD ONLY")+"</small></div><div class='top-right'><button class='icon-help' data-action='help'>?</button><button class='btn btn-small btn-outline desktop-create' data-action='new-group'>+ New Ajo circle</button><span class='avatar avatar-top'>"+esc(initials(S.data.user.name))+"</span><button class='quiet-icon' data-view='settings'>⌄</button></div></header><main class='app-content'>"+content()+"</main><footer class='app-footer'><span>Trust Ajo · sample records are clearly labelled</span><span>Nothing here moves or holds real money.</span></footer></section></div>";
}
function modalHead(k,t){return"<div class='modal-head'><div><small class='section-kicker'>"+k+"</small><h2>"+t+"</h2></div><button class='modal-close' data-action='close-modal'>×</button></div>";}
function openModal(s){modal.innerHTML="<div class='modal-backdrop'><section class='modal-card' role='dialog' aria-modal='true' aria-label='Trust Ajo dialog'>"+s+"</section></div>";const first=modal.querySelector("input,select,button,[tabindex='0']");if(first)requestAnimationFrame(()=>first.focus());}
function closeModal(){modal.innerHTML="";}
function dateInputValue(date){return new Date(date).toISOString().slice(0,10);}
function firstDueDateDefault(frequency){const d=new Date();d.setUTCHours(12,0,0,0);if(frequency==="Monthly"){const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(Math.min(day,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));}else d.setUTCDate(d.getUTCDate()+7);return dateInputValue(d);}
function groupModal(){const minDate=dateInputValue(new Date());openModal(modalHead("START A CIRCLE","Set the rhythm together.")+"<p class='modal-lead'>Agree the amount, schedule, and member count together. We’ll flag due-date overlaps with your other circles.</p><form data-form='create-group' class='modal-form'><label>Circle name<input name='name' required minlength='3' maxlength='60' placeholder='e.g. Saturday Sellers'></label><label>Shared goal <small>OPTIONAL</small><input name='purpose' maxlength='160' placeholder='What are you saving for?'></label><div class='form-pair'><label>Contribution amount (NGN)<input type='number' min='1000' max='1000000' step='100' name='contributionAmount' required placeholder='25000'></label><label>Frequency<select name='frequency'><option>Weekly</option><option>Monthly</option></select></label></div><label>First contribution due<input type='date' name='firstDueDate' min='"+minDate+"' value='"+firstDueDateDefault("Weekly")+"' required></label><label>Member capacity<input type='number' min='3' max='20' name='capacity' value='5' required></label><div class='modal-note'>Share this code privately. Organizers can rotate it if it is exposed. The app checks capacity and due-date clashes before a member joins.</div><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary' type='submit'>Create circle</button></div></form>");}
function details(id){
 const g=(S.data.groups||[]).find(x=>x.id===id);if(!g)return;
  const members=(g.members||[]).map((m,i)=>"<div class='member-line'><span class='face'>"+esc(initials(m.name))+"</span><div><b>"+esc(m.name)+(m.userId===S.data.user.id?" <small>(you)</small>":"")+"</b><small>"+esc(m.role)+"</small></div><i>"+(i+1)+"</i></div>").join("");
  const invite=g.joinCode?"<div class='invite-code-block'><div><b>Invite a member</b><small>Share privately. Rotate the code if it is exposed.</small></div><code>"+esc(g.joinCode)+"</code><button class='btn btn-outline btn-small' data-action='copy-code' data-code='"+esc(g.joinCode)+"'>Copy</button><button class='btn btn-quiet btn-small' data-action='rotate-code' data-id='"+esc(g.id)+"'>Rotate code</button></div>":"";
  const paymentNote=S.data.paymentMode==="flutterwave-test"?"Flutterwave test checkout · no real funds move.":"Local sample record only · no money moves.";
  const contributionButton=g.memberCount<g.capacity?"<button class='btn btn-outline' disabled>Waiting for "+(g.capacity-g.memberCount)+" more member(s)</button>":(!dueNow(g.nextDueAt)?"<button class='btn btn-outline' disabled>Contributions open "+date(g.nextDueAt)+"</button>":(S.data.paymentMode==="flutterwave-test"?"<button class='btn btn-primary' data-action='pay-now' data-id='"+esc(g.id)+"'>Pay with Flutterwave · test</button>":"<button class='btn btn-primary' data-action='contribute-now' data-id='"+esc(g.id)+"'>Record test contribution</button>"));
  openModal(modalHead("CIRCLE DETAILS",esc(g.name))+"<p class='modal-lead'>"+esc(g.purpose||"A shared savings circle")+" · "+g.frequency+" · "+cash(g.contributionAmount)+" each cycle</p><div class='detail-progress'><b>"+g.paidThisCycle+" / "+g.memberCount+" contributions recorded</b><span>Due "+date(g.nextDueAt)+"</span></div><div class='progress'><span style='width:"+Math.round(g.paidThisCycle/Math.max(1,g.memberCount)*100)+"%'></span></div><div class='member-list-head'><b>Agreed payout rotation</b><span>"+g.payoutOrder.length+" turns</span></div><div class='member-list'>"+members+"</div>"+invite+"<div class='modal-note'>ⓘ &nbsp;"+paymentNote+" Payouts are not automated. When everyone records a contribution, the schedule advances to the next turn; no payout is sent.</div><div class='modal-actions'><button class='btn btn-quiet' data-action='close-modal'>Close</button>"+(g.myContributionStatus==="due"?contributionButton:"<button class='btn btn-primary' data-action='close-modal'>Done</button>")+"</div>");
}
function shareModal(){const synthetic=S.data.passport.sampleProfile;const fields=synthetic?"<label><input type='checkbox' name='scopes' value='businessActivity' checked><span><b>Business activity</b><small>Synthetic sample summary</small></span></label><label><input type='checkbox' name='scopes' value='incomePattern' checked><span><b>Average monthly inflow</b><small>Synthetic sample amount only</small></span></label><label><input type='checkbox' name='scopes' value='consistency'><span><b>Income pattern</b><small>Synthetic sample indicator only</small></span></label><label><input type='checkbox' name='scopes' value='savingsBehaviour'><span><b>Savings habit</b><small>Synthetic sample indicator only</small></span></label>":"";openModal(modalHead("BUSINESS PROGRESS","Choose what to share.")+"<p class='modal-lead'>The link expires after 24 hours. Anyone with the link can open it. Revoke access at any time.</p><form data-form='share' class='share-form'><label><input type='checkbox' name='scopes' value='profile' checked><span><b>Profile name and business</b><small>Name, business name and type</small></span></label>"+fields+"<div class='modal-note'>▣ &nbsp;Only the selected sections appear in the link. Do not share the link publicly.</div><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary' type='submit'>Create private link ↗</button></div></form>");}
function linkModal(url){openModal(modalHead("LINK READY","Your Passport link is live.")+"<p class='modal-lead'>Share it with the person you chose. It expires in 24 hours.</p><label class='copy-field'>Private link<input id='share-url' readonly value='"+esc(url)+"'></label><div class='modal-note'>▣ &nbsp;Revoke this link from Business progress at any time.</div><div class='modal-actions'><button class='btn btn-quiet' data-action='close-modal'>Done</button><button class='btn btn-primary' data-action='copy-link'>Copy link</button></div>");}
function businessEntryModal(entry){const today=dateInputValue(new Date()),editing=Boolean(entry),type=entry?.type||"income",categories=type==="expense"?["Stock","Transport","Utilities","Marketing","Equipment","Other expense"]:["Sales","Services","Other income"],category=entry?.category||categories[0];openModal(modalHead("BUSINESS PROGRESS",editing?"Edit this business record.":"Add a business record.")+"<p class='modal-lead'>Record money in or money out. Ajo contributions are tracked separately in your circles.</p><form data-form='business-entry' class='business-entry-form'><input type='hidden' name='entryId' value='"+esc(entry?.id||"")+"'><label>Record type<select name='type' required><option value='income' "+(type==="income"?"selected":"")+">Money in · income</option><option value='expense' "+(type==="expense"?"selected":"")+">Money out · expense</option></select></label><label>Category<select name='category' required>"+categories.map(value=>"<option "+(category===value?"selected":"")+">"+value+"</option>").join("")+"</select></label><div class='form-pair'><label>Amount in naira<input name='amount' type='number' min='1' max='1000000000' step='1' inputmode='numeric' required placeholder='e.g. 15000' value='"+(entry?esc(entry.amount):"")+"'></label><label>Date<input name='entryDate' type='date' max='"+today+"' value='"+esc(entry?.entryDate||today)+"' required></label></div><label>Note <small>OPTIONAL · UP TO 120 CHARACTERS</small><input name='note' maxlength='120' placeholder='What was this for?' value='"+esc(entry?.note||"") +"'></label><div class='modal-note'>These are your own records. No bank account is connected and no payment is verified.</div><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary' type='submit'>"+(editing?"Save changes":"Save record")+"</button></div></form>");}
function businessGoalModal(){const goal=S.data.user.monthlyIncomeGoal||"";openModal(modalHead("BUSINESS PROGRESS","Set your monthly income goal.")+"<p class='modal-lead'>Choose a target to compare with the income you record this month. This is a planning tool, not a forecast.</p><form data-form='business-goal' class='business-entry-form'><label>Monthly income goal in naira<input name='monthlyIncomeGoal' type='number' min='0' max='1000000000' step='1' inputmode='numeric' value='"+esc(goal)+"' placeholder='e.g. 350000'></label><div class='modal-note'>Leave blank or enter 0 to remove your goal.</div><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary' type='submit'>Save goal</button></div></form>");}
function helpModal(){openModal(modalHead("A QUICK GUIDE","Clear records for community savings.")+"<div class='guide'><p><b>01 · Agree on the circle.</b> Set the amount, schedule, member capacity and payout order.</p><p><b>02 · Review before joining.</b> Invitees can see the commitment and schedule; the app checks for same-day due-date clashes.</p><p><b>03 · Try the payment journey.</b> Flutterwave sandbox checkout uses test credentials and does not move real money. Without sandbox credentials, this app records a test contribution locally. No payout is sent; the order is only a schedule.</p><p><b>04 · Track business progress.</b> Record income and expenses and compare trends. These manual records are not bank verified.</p></div><div class='modal-actions'><button class='btn btn-primary' data-action='close-modal'>Got it</button></div>");}
async function runAction(name,el){
 if(S.busy)return;
 try{
  if(name==="show-login"){showAuth("login");return;}if(name==="show-signup"){showAuth("signup");return;}if(name==="home"){S.page="landing";page("landing");return;}if(name==="login"){showAuth("login");return;}if(name==="signup"){showAuth("signup");return;}
  if(name==="sample-workspace"){if(S.supabaseAuth){toast("Sign in with your account to continue.",true);return;}S.busy=true;await api("/api/auth/demo","POST",{});S.data=await api("/api/bootstrap");S.view="overview";S.page="app";renderApp();page("app");toast("Welcome to the sample workspace.");return;}
  if(name==="new-group"){groupModal();return;}if(name==="dismiss-join-preview"){S.joinPreview=null;renderApp();return;}if(name==="confirm-join"){if(!S.joinPreview||S.joinPreview.conflict)throw new Error("Review a valid circle invite before joining.");const joining=S.joinPreview.group;S.busy=true;S.data=await api("/api/groups/join","POST",{joinCode:S.joinPreview.joinCode});S.joinPreview=null;renderApp();toast("You joined "+joining.name+". Check the due date before contributing.");return;}if(name==="rotate-code"){if(!confirm("Replace this invite code? The old code will stop working."))return;S.busy=true;S.data=await api("/api/groups/invite/rotate","POST",{groupId:el.dataset.id});renderApp();const rotated=S.data.groups.find(g=>g.id===el.dataset.id);toast(rotated?"New invite code: "+rotated.joinCode:"Invite code changed.");return;}if(name==="details"){details(el.dataset.id);return;}
  if(name==="pay-now"){S.busy=true;const checkout=await api("/api/groups/pay","POST",{groupId:el.dataset.id});if(!checkout.checkoutUrl)throw new Error("Flutterwave did not return a checkout link.");location.assign(checkout.checkoutUrl);return;}
  if(name==="contribute-now"){S.busy=true;S.data=await api("/api/groups/contribute","POST",{groupId:el.dataset.id});const cycleCompleted=S.data.cycleCompleted;S.view="groups";closeModal();renderApp();toast(cycleCompleted?"Test cycle recorded. Schedule moved to the next member; no payout was sent.":"Test contribution recorded. No funds moved.");return;}
  if(name==="verify"){S.busy=true;S.data=await api("/api/verification/demo","POST",{kind:el.dataset.kind});renderApp();toast("Mock verification completed.");return;}
   if(name==="business-period"){if(["daily","weekly","monthly","yearly"].includes(el.dataset.period)){S.businessPeriod=el.dataset.period;renderApp();}return;}
   if(name==="add-business-entry"){businessEntryModal();return;}
   if(name==="edit-business-entry"){const entry=(S.data.businessEntries||[]).find(x=>x.id===el.dataset.id);if(entry)businessEntryModal(entry);return;}
   if(name==="set-business-goal"){businessGoalModal();return;}
   if(name==="business-filter"){S.businessFilter=el.dataset.filter||"all";S.businessHistoryExpanded=false;renderApp();return;}
   if(name==="clear-business-search"){S.businessSearch="";S.businessFilter="all";S.businessHistoryExpanded=false;renderApp();return;}
   if(name==="export-business-csv"){const rows=filteredBusinessEntries();if(!rows.length)return;const quote=v=>'"'+String(v??"").replaceAll('"','""')+'"';const csv=[["Date","Type","Category","Amount (NGN)","Note","Source"],...rows.map(x=>[x.entryDate,x.type,x.category,x.amount,x.note,String(x.id).startsWith("seed-business-")?"Sample data":"Manual entry"])].map(row=>row.map(quote).join(",")).join("\r\n");const link=document.createElement("a"),url=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));link.href=url;link.download="trust-ajo-business-records-"+dateInputValue(new Date())+".csv";link.click();URL.revokeObjectURL(url);toast("Filtered records exported.");return;}
   if(name==="toggle-business-history"){S.businessHistoryExpanded=!S.businessHistoryExpanded;renderApp();return;}
   if(name==="delete-business-entry"){if(!confirm("Delete this business record?"))return;S.busy=true;S.data=await api("/api/business/entries/"+encodeURIComponent(el.dataset.id),"DELETE");S.businessHistoryExpanded=false;renderApp();toast("Business record deleted.");return;}
   if(name==="share"){shareModal();return;}
  if(name==="revoke"){if(!confirm("Revoke this Passport link?"))return;S.busy=true;S.data=await api("/api/passport/revoke","POST",{id:el.dataset.id});renderApp();toast("Business profile link revoked.");return;}
  if(name==="buy"){const p=S.data.products.find(x=>x.id===el.dataset.id);if(!p||!confirm("Save a sample order for "+p.name+"? This won’t charge you."))return;S.busy=true;S.data=await api("/api/commerce/checkout","POST",{productId:p.id});S.view="activity";renderApp();toast("Sample order saved. No payment was made.");return;}
  if(name==="sample-ref"){S.view="trust";S.trust=null;renderApp();document.querySelector("[name=amount]").value=el.dataset.amount;document.querySelector("[name=reference]").value=el.dataset.ref;return;}
  if(name==="logout"){if(S.authClient)await S.authClient.auth.signOut({scope:"local"});else await api("/api/auth/logout","POST",{});S.data=null;S.view="overview";S.page="landing";page("landing");return;}
  if(name==="help"){helpModal();return;}if(name==="close-modal"){closeModal();return;}if(name==="toast-close"){toastBox.innerHTML="";return;}
  if(name==="copy-link"){const f=document.getElementById("share-url");try{await navigator.clipboard.writeText(f.value);}catch(e){f.focus();f.select();document.execCommand("copy");}toast("Private profile link copied.");return;}
  if(name==="copy-code"){try{await navigator.clipboard.writeText(el.dataset.code);}catch(e){toast("Select and copy the invite code: "+el.dataset.code,true);return;}toast("Invite code copied. Share it with your circle.");return;}
  if(name==="refresh"){S.data=await api("/api/bootstrap");renderApp();toast("Activity refreshed.");return;}if(name==="overview"){S.view="overview";renderApp();return;}
  if(name==="mobile-menu"){const menu=document.querySelector(".landing-links"),open=menu.classList.toggle("menu-open");el.setAttribute("aria-expanded",String(open));return;}if(name==="sidebar-toggle"){const sidebar=document.querySelector(".sidebar"),open=sidebar.classList.toggle("sidebar-open");el.setAttribute("aria-expanded",String(open));el.setAttribute("aria-label",open?"Close navigation":"Open navigation");return;}
 }catch(e){toast(e.message||"Something went wrong.",true);}finally{S.busy=false;}
}
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();document.querySelector(".sidebar.sidebar-open")?.classList.remove("sidebar-open");document.querySelector(".landing-links.menu-open")?.classList.remove("menu-open");}});
document.addEventListener("click",e=>{
 const side=document.querySelector(".sidebar.sidebar-open");if(side&&!e.target.closest(".sidebar")&&!e.target.closest("[data-action=sidebar-toggle]"))side.classList.remove("sidebar-open");const menu=document.querySelector(".landing-links.menu-open");if(menu&&!e.target.closest(".landing-links")&&!e.target.closest("[data-action=mobile-menu]"))menu.classList.remove("menu-open");
 if(e.target.classList.contains("modal-backdrop")){closeModal();return;}
 const v=e.target.closest("[data-view]");if(v){S.view=v.dataset.view;S.trust=null;renderApp();return;}
 const t=e.target.closest("[data-theme-choice]");if(t){const select=document.getElementById("theme-select");if(select){select.value=t.dataset.themeChoice;theme(select.value);document.querySelectorAll("[data-theme-choice]").forEach(x=>x.classList.toggle("selected",x===t));}return;}
 const b=e.target.closest("[data-action]");if(b)runAction(b.dataset.action,b);
});
document.addEventListener("input",e=>{if(e.target?.id!=="business-search")return;S.businessSearch=e.target.value;const pos=e.target.selectionStart;renderApp();const next=document.getElementById("business-search");if(next){next.focus();next.setSelectionRange(pos,pos);}});
document.addEventListener("change",e=>{if(e.target&&e.target.id==="theme-select"){theme(e.target.value);document.querySelectorAll("[data-theme-choice]").forEach(x=>x.classList.toggle("selected",x.dataset.themeChoice===e.target.value));}if(e.target&&e.target.name==="frequency"&&e.target.closest("form[data-form=create-group]")){const due=e.target.form.elements.firstDueDate;if(due)due.value=firstDueDateDefault(e.target.value);}if(e.target&&e.target.name==="type"&&e.target.closest("form[data-form=business-entry]")){const category=e.target.form.elements.category;const values=e.target.value==="expense"?["Stock","Transport","Utilities","Marketing","Equipment","Other expense"]:["Sales","Services","Other income"];category.innerHTML=values.map(value=>"<option>"+esc(value)+"</option>").join("");}});
document.addEventListener("submit",async e=>{
 const f=e.target.closest("form[data-form]");if(!f)return;e.preventDefault();if(S.busy)return;
 const kind=f.dataset.form,fd=new FormData(f);let body={};fd.forEach((v,k)=>body[k]=v);
 try{
  S.busy=true;
  if(kind==="login"){
   if(S.authClient){const {data,error}=await S.authClient.auth.signInWithPassword({email:body.email,password:body.password});if(error||!data.session)throw new Error("Email or password was not recognized.");}
   else await api("/api/auth/login","POST",body);
   S.authNotice="";S.data=await api("/api/bootstrap");S.view="overview";S.page="app";renderApp();page("app");toast("Welcome back.");return;
  }
  if(kind==="register"){
   if(S.authClient){const {data,error}=await S.authClient.auth.signUp({email:body.email,password:body.password,options:{data:{name:body.name,business_name:body.businessName,business_type:body.businessType},emailRedirectTo:location.origin}});if(error)throw new Error(error.message);if(!data.session){S.mode="login";S.authNotice="Check your email to confirm your account, then sign in.";renderAuth();return;}}
   else await api("/api/register","POST",body);
   S.authNotice="";S.data=await api("/api/bootstrap");S.view="overview";S.page="app";renderApp();page("app");toast("Your Trust Ajo space is ready.");return;
  }
  if(kind==="business-entry"){const id=body.entryId;delete body.entryId;S.data=await api(id?"/api/business/entries/"+encodeURIComponent(id):"/api/business/entries",id?"PUT":"POST",body);S.view="passport";S.businessHistoryExpanded=false;closeModal();renderApp();toast(id?"Business record updated.":"Business record saved.");return;}
  if(kind==="business-goal"){S.data=await api("/api/business/goal","POST",body);S.view="passport";closeModal();renderApp();toast("Monthly income goal saved.");return;}
   if(kind==="create-group"){S.data=await api("/api/groups/create","POST",body);S.page="app";S.view="groups";closeModal();renderApp();const g=S.data.groups.find(x=>x.name===body.name&&x.joinCode);toast(g?"Circle created. Invite code: "+g.joinCode:"Your circle is ready.");return;}
   if(kind==="join-group"){const joinCode=String(body.joinCode||"").trim().toUpperCase();const result=await api("/api/groups/invite?code="+encodeURIComponent(joinCode));S.joinPreview={...result,joinCode};S.view="groups";renderApp();return;}
  if(kind==="trust"){S.trust=await api("/api/trust/check","POST",body);renderApp();return;}
  if(kind==="settings"){body.contributionReminders=f.elements.contributionReminders.checked;body.weeklyDigest=f.elements.weeklyDigest.checked;body.shareAlerts=f.elements.shareAlerts.checked;S.data=await api("/api/settings","POST",body);theme(S.data.user.preferences.theme);renderApp();toast("Settings saved.");return;}
  if(kind==="share"){body={scopes:Array.from(f.querySelectorAll("input[name=scopes]:checked")).map(x=>x.value)};const link=await api("/api/passport/share","POST",body);S.data=await api("/api/bootstrap");S.view="passport";renderApp();linkModal(link.url);return;}
 }catch(err){toast(err.message||"Something went wrong.",true);}finally{S.busy=false;}
});
document.addEventListener("change",e=>{if(e.target&&e.target.name==="theme"&&e.target.closest("form[data-form=settings]"))theme(e.target.value);});
async function shareView(token){
 S.page="share";landing.classList.add("hidden");auth.classList.add("hidden");workspace.classList.add("hidden");shared.classList.remove("hidden");theme("light");shared.innerHTML="<div class='share-loading'>Opening your shared business profile…</div>";
 try{const r=await api("/api/share?token="+encodeURIComponent(token)),m=r.metrics||{};let parts="";
  if(m.profile)parts+="<article class='shared-profile'><span>"+esc(initials(m.profile.name))+"</span><div><b>"+esc(m.profile.name)+"</b><small>"+esc(m.profile.businessName)+" · "+esc(m.profile.businessType)+"</small></div></article>";
  if(m.businessActivity)parts+="<article><small>BUSINESS ACTIVITY</small><b>"+esc(m.businessActivity)+"</b></article>";
  if(m.incomePattern)parts+="<article><small>AVERAGE MONTHLY INFLOW</small><b>"+cash(m.incomePattern.monthlyInflow)+"</b><small>Illustrative sample figures</small></article>";
  if(m.consistency!==undefined)parts+="<article><small>INCOME CONSISTENCY</small><b>"+esc(m.consistency)+"%</b></article>";
  if(m.savingsBehaviour!==undefined)parts+="<article><small>SAVINGS BEHAVIOUR</small><b>"+esc(m.savingsBehaviour)+"%</b></article>";
  shared.innerHTML="<header><a class='brand' href='/'><span class='brand-mark'><b>TA</b><i></i></span><span class='brand-word'><strong>Trust Ajo</strong><small>Save together. Build trust.</small></span></a><span class='shared-lock'>▣ Permission-limited view</span></header><section class='shared-card'><small class='section-kicker'>SHARED BUSINESS PROFILE</small><h1>Progress, shared by choice.</h1><p>Only the sections selected by the account owner appear here. Expires "+date(r.expiresAt)+".</p><div class='shared-grid'>"+parts+"</div><footer>"+(r.sampleData?"Fictional sample information only; not real financial history.":"Profile details shared by the account owner; no financial source is connected.")+"</footer></section>";
 }catch(err){shared.innerHTML="<header><a class='brand' href='/'><span class='brand-mark'><b>TA</b><i></i></span><span class='brand-word'><strong>Trust Ajo</strong><small>Save together. Build trust.</small></span></a></header><section class='shared-card'><h1>This Passport link isn’t available.</h1><p>"+esc(err.message)+"</p><a class='btn btn-primary' href='/'>Return to Trust Ajo</a></section>";}
}
async function start(){const config=await api("/api/config");S.supabaseAuth=Boolean(config.supabaseAuth?.enabled);if(S.supabaseAuth){if(!window.supabase?.createClient)throw new Error("Supabase client could not be loaded.");S.authClient=window.supabase.createClient(config.supabaseAuth.url,config.supabaseAuth.publishableKey);document.querySelectorAll("[data-action='sample-workspace']").forEach(el=>el.hidden=true);}const params=new URLSearchParams(location.search),token=params.get("token"),paymentResult=params.get("payment");if(token){shareView(token);return;}try{S.data=await api("/api/bootstrap");S.page="app";theme(S.data.user.preferences.theme);renderApp();page("app");if(paymentResult){history.replaceState(null,"",location.pathname);const messages={success:"Flutterwave verified your contribution.",cancelled:"Checkout was cancelled; no contribution was recorded.",failed:"Payment was not confirmed. Check your activity before retrying.",pending:"Payment is still being verified. Refresh your activity shortly.",review:"Payment needs review before it can count toward the circle.",unknown:"Payment could not be matched to a circle."};toast(messages[paymentResult]||"Payment status updated.",paymentResult!=="success");}}catch(e){S.page="landing";page("landing");}}
start();
})(); 
